def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform full-height/full-width separator lines divide the panels.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    def runs(n, seps):
        parts=[]; start=0
        for i in range(n):
            if i in seps:
                if start < i: parts.append((start, i))
                start=i+1
        if start<n: parts.append((start,n))
        return parts
    rows, cols = runs(h, sep_rows), runs(w, sep_cols)
    out=[]
    for r0,r1 in rows:
        line=[]
        for c0,c1 in cols:
            vals=[grid[r][c] for r in range(r0,r1) for c in range(c0,c1)]
            freq={v:vals.count(v) for v in set(vals)}
            base=max(freq, key=freq.get)
            other=sum(n for v,n in freq.items() if v != base)
            if other == 0:
                line.append(0 if base == 0 else base)
            elif other == 1:
                line.append(base)
            else:
                line.append(1)
        out.append(line)
    return out
